<?php namespace ProcessWire;

/**
 * Video Files: class names of Bootstrap 5 for videos on the website
 *
 * Choose it in the settings of the module "Video Files" (CSS framework of the website), or
 * for a single video: $video->render([ 'framework' => 'bootstrap5' ]). The module does not
 * load Bootstrap. Your website has to include its stylesheet. Made for Bootstrap 5.0 to 5.3;
 * Bootstrap's script is not needed.
 *
 * To change this profile, do not edit this file: it is replaced with every update of the
 * module. Create /site/templates/selfhostedvideo/frameworks/bootstrap5.php instead, which is then
 * used in place of this file. It can name only what it changes:
 *
 *     return array(
 *         'extends' => 'bootstrap5',
 *         'parts' => array(
 *             'caption' => 'mt-2 text-center',
 *             'title' => false,  // false: this part is left to the module again
 *         ),
 *     );
 *
 * The format of a profile is explained in the head of uikit3.php and under "CSS frameworks"
 * in the README, which also lists all parts.
 *
 * This file is part of the FieldtypeSelfHostedVideo module for ProcessWire 3.x
 *
 */

if(!defined("PROCESSWIRE")) die();

return array(

	'title' => 'Bootstrap 5',

	'parts' => array(

		// a video with controls
		'player' => 'mb-3',

		// Overlays: text and links on the picture. Colours that stay the same in Bootstrap's dark
		// mode, as the picture below them does. Both colour classes win over the colours of links.
		'overlay' => 'rounded',
		'overlay-dark' => 'bg-dark text-white',
		'overlay-light' => 'bg-light text-dark',

		// The list of chapters below the video: a list group without outer borders. The link of a
		// chapter fills its item and is marked under the pointer, the chapter being played is
		// bold on a grey ground. For Bootstrap's coloured bar there, see the README.
		'chapters' => 'mt-3',
		'chapters-label' => 'fw-bold mb-2',
		'chapter-list' => 'list-group list-group-flush',
		'chapter-item' => array('class' => 'list-group-item p-0', 'current' => 'list-group-item-secondary'),
		'chapter' => array('class' => 'list-group-item-action text-decoration-none px-3 py-2', 'current' => 'fw-bold'),

		// title, duration and description below the video
		'caption' => 'mt-2',
		'title' => 'fw-bold fs-5',
		'meta' => 'small text-muted',
		'description' => 'small',

		// More about the video (the custom fields, in a box that opens): a description list in
		// Bootstrap's grid, names beside values from the "sm" width on. Without gutters, which
		// would reach out of the video where it is not inside a container; the names keep their
		// distance by a padding. The box is a card of Bootstrap, grey where the version knows the
