		'info' => 'card card-body bg-body-tertiary py-2 px-3 mt-3',
		'transcript' => 'card card-body bg-body-tertiary py-2 px-3 mt-3',
		'transcript-body' => 'mt-2',
		'info-list' => 'row gx-0 mt-2 mb-0',
		'info-term' => 'col-sm-4 pe-sm-3',
		'info-value' => 'col-sm-8',

		// The two buttons on the picture (full screen, pause of a background video) keep the look
